async function getSessionCookie() {
    // 1. 登录参数 + 原生转换为form表单格式
    const loginData = { next: '', username: 'admin', password: '54pwd@2022', remember: 'on' };
    const formData = Object.keys(loginData)
        .map(k => `${encodeURIComponent(k)}=${encodeURIComponent(loginData[k])}`)
        .join('&');

    // 2. 请求配置（保留核心必要项）
    const options = {
        method: 'POST',
        uri: 'http://192.168.3.31:3000/',
        body: formData,
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/120.0.0.0 Safari/537.36'
        },
        timeout: 10000,
        followRedirect: true,
        resolveWithFullResponse: true, // 必须保留：获取响应头
        simple: false // 允许所有状态码
    };

    // 3. 发送请求 + 解析Cookie
    let result = {};
    try {
        const res = await this.helpers.request(options);
        let cookie = '';
        // 解析session cookie
        const setCookie = res.headers['set-cookie'];
        if (setCookie && Array.isArray(setCookie)) {
            cookie = setCookie.find(c => c.startsWith('session='))?.split(';')[0] || '';
        }
        // 0标记：有请求无cookie；有cookie则返回实际值
        result = {
            status: "success",
            cookie: cookie || '0',
            message: cookie ? '获取cookie成功' : '登录成功但无cookie'
        };
    } catch (err) {
        // 1标记：请求错误
        result = {
            status: "error",
            cookie: '1',
            message: err.message,
            details: err.response?.body || "无详细信息"
        };
    }

    // 4. n8n标准返回格式
    return [{
        json: {
            totalRequests: 1,
            details: [result]
        }
    }];
}

return getSessionCookie();

